<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\TemplateAsset\Application\Service\Visibility;

use Psr\EventDispatcher\EventDispatcherInterface;

use Iterator;
use Throwable;

use Civi\Lughauth\Features\Access\Tenant\Application\Service\Visibility\TenantVisibilityService;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\TemplateAssetRef;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\TemplateAssetAttributes;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\TemplateAsset;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\Gateway\TemplateAssetFilter;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\Gateway\TemplateAssetCursor;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\Gateway\TemplateAssetReadGateway;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\Gateway\TemplateAssetSlide;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\Gateway\TemplateAssetWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class TemplateAssetVisibilityService
{
  use LoggerAwareTrait;
  use TracerAwareTrait;

  public function __construct(
    private readonly EventDispatcherInterface $dispatcher,
    private readonly TemplateAssetReadGateway $readGateway,
    private readonly TemplateAssetWriteGateway $writeGateway,
    private readonly TenantVisibilityService $tenantVisibilityService  ) {
  }

  public function prepareVisibleDataInList(TemplateAsset $content): TemplateAssetAttributes
  {
    return $this->prepareVisibleDataCallback($content, true);  }
  public function prepareVisibleData(TemplateAsset $content): TemplateAssetAttributes
  {
    return $this->prepareVisibleDataCallback($content, false);  }
  public function copyWithFixed(TemplateAssetAttributes $attributes, ?TemplateAsset $original = null): TemplateAssetAttributes
  {
    $this->logDebug("Copy with fixed for Template asset");
    $span = $this->startSpan("Copy with fixed for  Template asset");
    try {
      $visible = $this->visiblesReferences($attributes);
      $fixed = $this->fieldsToFix($original);
      foreach ($fixed as $field) {
        $visible->unset($field);
      }
      $result = $this->dispatcher->dispatch(new TemplateAssetPresetValues($attributes, $original));
      return $result->attributes;
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }

  public function copyWithHidden(TemplateAssetAttributes $attributes, ?TemplateAsset $original = null): TemplateAssetAttributes
  {
    $this->logDebug("Copy with hidden for Template asset");
    $span = $this->startSpan("Copy with hidden for  Template asset");
    try {
      $hidden = $this->fieldsToHide($original);
      foreach ($hidden as $field) {
        $attributes->unset($field);
      }
      return $attributes;
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }

  public function checkVisibility(Iterator|string|TemplateAssetRef $value): bool
  {
    $this->logDebug("Check visibility of an iterator for Template asset");
    $span = $this->startSpan("Check visibility of an iterator for  Template asset");
    try {
      if (is_string($value)) {
        return !!$this->retrieveVisibleForUpdate(new TemplateAssetRef( $value ) );
      } else if ($value instanceof TemplateAssetRef) {
        return !!$this->retrieveVisibleForUpdate($value );
      } else if ($value instanceof Iterator) {
        $ids = [];
        foreach ($value as $val) {
          $ids[] = $val->uid();
        }
        $filter = new TemplateAssetFilter(uids: $ids);
        return count($ids) == $this->countVisibles($filter);
      } else {        return false;      }
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function listVisibles(TemplateAssetFilter $filter, ?TemplateAssetCursor $cursor = null): TemplateAssetSlide
  {
    $this->logDebug("List visibles for Template asset");
    $span = $this->startSpan("List visibles for  Template asset");
    try {
      $visibleFilter = $this->applyPreVisibilityFilter($filter);
      $result = $this->readGateway->list($visibleFilter, $cursor);
      return $result->slide(function(TemplateAsset $item): bool {
        return $this->evaluatePostVisibility($item);
      });
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function countVisibles(TemplateAssetFilter $filter): int
  {
    $this->logDebug("Count visibles for Template asset");
    $span = $this->startSpan("Count visibles for  Template asset");
    try {
      $visibleFilter = $this->applyPreVisibilityFilter($filter);
      return $this->readGateway->count($visibleFilter);
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function listVisiblesForUpdate(TemplateAssetFilter $filter, ?TemplateAssetCursor $cursor = null): TemplateAssetSlide
  {
    $this->logDebug("List visibles for update for Template asset");
    $span = $this->startSpan("List visibles for update for  Template asset");
    try {
      $visibleFilter = $this->applyPreVisibilityFilter($filter);
      $result = $this->writeGateway->listForUpdate($visibleFilter, $cursor);
      return $result->slide(function(TemplateAsset $item): bool {
        return $this->evaluatePostVisibility($item);
      });
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function countVisiblesForUpdate(TemplateAssetFilter $filter): int
  {
    $this->logDebug("Count visibles for update for Template asset");
    $span = $this->startSpan("Count visibles for update for  Template asset");
    try {
      $visibleFilter = $this->applyPreVisibilityFilter($filter);
      return $this->writeGateway->countForUpdate($visibleFilter);
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function retrieveVisible(TemplateAssetRef $ref): ?TemplateAsset
  {
    $this->logDebug("Retrieve visible for Template asset");
    $span = $this->startSpan("Retrieve visible for  Template asset");
    try {
      $filter = new TemplateAssetFilter(uids: [$ref->uid()]);
      $visibleFilter = $this->applyPreVisibilityFilter($filter);
      if ($readed = $this->readGateway->retrieve($visibleFilter)) {
        return $this->evaluatePostVisibility($readed) ? $readed : null;
      } else {
        return null;
      }
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function retrieveVisibleForUpdate(TemplateAssetRef $ref): ?TemplateAsset
  {
    $this->logDebug("Retrieve visible for update for Template asset");
    $span = $this->startSpan("Retrieve visible for update for  Template asset");
    try {
      $filter = new TemplateAssetFilter(uids: [$ref->uid()]);
      $visibleFilter = $this->applyPreVisibilityFilter($filter);
      if( $readed = $this->writeGateway->retrieveForUpdate($visibleFilter) ) {
        return $this->evaluatePostVisibility($readed) ? $readed : null;
      } else {
        return null;
      }
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function fieldsToFix(?TemplateAssetRef $ref = null): array
  {
    $this->logDebug("Check fields to fix for Template asset");
    $span = $this->startSpan("Check fields for fix for Template asset");
    try {
      $result = $this->dispatcher->dispatch(new TemplateAssetCollectNonEditableFields(TemplateAsset::calculatedFields(), $ref));
      return array_values( array_unique( array_merge( $this->fieldsToHide($ref), $result->fields) ) );
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }

  public function fieldsToHide(?TemplateAssetRef $ref = null): array
  {
    $this->logDebug("Check fields to hide for Template asset");
    $span = $this->startSpan("Check fields to hide for  Template asset");
    try {
      $result = $this->dispatcher->dispatch(new TemplateAssetCollectNonVisibleFields([], $ref));
      return array_values( array_unique( $result->fields ) );
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }

  private function visiblesReferences(TemplateAssetAttributes $attributes): TemplateAssetAttributes
  {
    $this->logDebug("Check visibility of parent references for Template asset");
    $span = $this->startSpan("Check visibility of parent references for  Template asset");
    try {
      $tenant = $attributes->getTenant();      if( null !== $tenant && !$this->tenantVisibilityService->checkVisibility($tenant) ) {
        throw new NotFoundException("Unknown Tenant " . ( $tenant->uid() ?? 'no-id'));
      }
      return $attributes;
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  private function applyPreVisibilityFilter(TemplateAssetFilter $filter): TemplateAssetFilter
  {
    $this->logDebug("Compose visibility filter for Template asset");
    $span = $this->startSpan("Compose visibility filter for  Template asset");
    try {
      $result = $this->dispatcher->dispatch(new TemplateAssetRestrictFilterToVisibility($filter));
      return $result->templateAssetFilter;
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  private function evaluatePostVisibility(TemplateAsset $value): bool
  {
    $this->logDebug("Check if item is visible for Template asset");
    $span = $this->startSpan("Check if item is visible for  Template asset");
    try {
      $result = $this->dispatcher->dispatch(new TemplateAssetVisibilityCheck(true, $value));
      return $result->visible;
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  private function prepareVisibleDataCallback(TemplateAsset $content, bool $inlist): TemplateAssetAttributes
  {
    $this->logDebug("Prepare hydration to visible data for Template asset");
    $span = $this->startSpan("Prepare hydration to visible data for Template asset");
    try {
      $attributes = $content->toAttributes();      $result = $this->dispatcher->dispatch(new TemplateAssetEnrichForView($content, $inlist, $attributes));
      return $result->getAttributes();
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
}
